import { useState } from 'react';
import { useForm, FormProvider, useFormContext } from 'react-hook-form';

export type WizardInputs = { name: string; email: string; tier: 'free' | 'pro' };

export function Wizard({ onSubmit }: { onSubmit: (data: WizardInputs) => void }) {
  const [step, setStep] = useState<1 | 2>(1);
  const methods = useForm<WizardInputs>({
    defaultValues: { name: '', email: '', tier: 'free' },
  });

  return (
    <FormProvider {...methods}>
      {step === 1 ? (
        <StepOne onNext={() => setStep(2)} />
      ) : (
        <StepTwo onBack={() => setStep(1)} onSubmit={methods.handleSubmit(onSubmit)} />
      )}
    </FormProvider>
  );
}

export function StepOne({ onNext }: { onNext: () => void }) {
  const { register } = useFormContext<WizardInputs>();
  return (
    <div>
      <input placeholder="name" {...register('name')} />
      <input placeholder="email" {...register('email')} />
      <button type="button" onClick={onNext}>
        Next
      </button>
    </div>
  );
}

export function StepTwo({
  onBack,
  onSubmit,
}: {
  onBack: () => void;
  onSubmit: () => void;
}) {
  const { register } = useFormContext<WizardInputs>();
  return (
    <div>
      <select {...register('tier')}>
        <option value="free">Free</option>
        <option value="pro">Pro</option>
      </select>
      <button type="button" onClick={onBack}>
        Back
      </button>
      <button type="button" onClick={onSubmit}>
        Submit
      </button>
    </div>
  );
}
